namespace Fanex.Tarus.Infrastructure.Extensions
{
    using System;
    using System.Web;
    using Sunplus.Accounting.Core.Configurations;
    using Sunplus.Accounting.Core.Extensions;
    using Sunplus.UMControllerLibrary;

    /// <summary>
